40.4.2 逆推法（从后往前）  已知最终结果，反向倒推初始状态。
示例：存款逆推，已知n年后存款，求初始本金
设年利率 r ，顺推公式 f ( n ) = f ( n − 1 ) ∗ ( 1 + r ) 逆推公式 f ( n − 1 ) = f ( n ) / ( 1 + r )  double calculatePrincipal ( double target , int n , double r ) { double f = target ; for ( int i = n ; i > 0 ; i -- ) { f = f / ( 1 + r ) ; } return f ; }

49.3.3 实现方式  循环队列通常通过数组实现，关键是如何判断队列满和队列空：
判空条件：front==rear且元素个数为0。
判满条件：通常通过预留一个空位置实现，即 (rear+1)%MAX_SIZE == front ，此时队列中实际可存储MAX_SIZE-1个元素。  # include <iostream> using namespace std ; const int MAX_SIZE = 100 ; class CircularQueue { private : int data [ MAX_SIZE ] ; int front ; //队头指针(指向队头元素) int rear ; //队尾指针(指向队尾元素的下一个位置) public : //构造函数:初始化空队列 CircularQueue ( ) { front = 0 ; rear = 0 ; } //入队 bool enqueue ( int val ) { if ( isFull ( ) ) { return false ; //队列满 } data [ rear ] = val ; rear = ( rear + 1 ) % MAX_SIZE ; //队尾指针循环后移 return true ; } //出队 bool dequeue ( ) { if ( isEmpty ( ) ) { return false ; //队列空 } front = ( front + 1 ) % MAX_SIZE ; //队头指针循环后移 return true ; } //取队头元素 int getFront ( ) { if ( isEmpty ( ) ) { throw "CircularQueue is empty" ; } return data [ front ] ; } //判空 bool isEmpty ( ) { return front == rear ; } //判满(预留一个空位置) bool isFull ( ) { return ( rear + 1 ) % MAX_SIZE == front ; } //获取大小 int getSize ( ) { return ( rear - front + MAX_SIZE ) % MAX_SIZE ; } } ;

55.2.1 斐波那契数列  问题定义： F ( 0 ) = 0 F ( 1 ) = 1 F ( n ) = F ( n − 1 ) + F ( n − 2 ) n ≥ 2 求第 n 项数值。  动态规划解法：
状态定义： d p [ i ] 表示第 i 个斐波那契数
转移方程： d p [ i ] = d p [ i − 1 ] + d p [ i − 2 ] 边界： d p [ 0 ] = 0 , d p [ 1 ] = 1  # include <vector> using namespace std ; int fibonacci ( int n ) { if ( n == 0 ) return 0 ; if ( n == 1 ) return 1 ; vector < int > dp ( n + 1 ) ; dp [ 0 ] = 0 ; dp [ 1 ] = 1 ; for ( int i = 2 ; i <= n ; i ++ ) { dp [ i ] = dp [ i - 1 ] + dp [ i - 2 ] ; } return dp [ n ] ; }  空间优化（仅保留两个前置变量，空间复杂度降至 O ( 1 ) ）  int fibonacciOptimized ( int n ) { if ( n == 0 ) return 0 ; if ( n == 1 ) return 1 ; int a = 0 , b = 1 , c ; for ( int i = 2 ; i <= n ; i ++ ) { c = a + b ; a = b ; b = c ; } return b ; }

55.2.2 爬楼梯问题  题意：每次可爬1阶或2阶，求登上 n 阶楼梯总方法数。
状态： d p [ i ] 爬到第 i 阶的方法数
转移： d p [ i ] = d p [ i − 1 ] + d p [ i − 2 ] 边界： d p [ 1 ] = 1 , d p [ 2 ] = 2  int climbStairs ( int n ) { if ( n == 1 ) return 1 ; vector < int > dp ( n + 1 ) ; dp [ 1 ] = 1 ; dp [ 2 ] = 2 ; for ( int i = 3 ; i <= n ; i ++ ) { dp [ i ] = dp [ i - 1 ] + dp [ i - 2 ] ; } return dp [ n ] ; }

55.2.3 最大子数组和  题意：给定整数数组，找出连续子数组的最大和（子数组至少一个元素）
状态： d p [ i ] 以第 i 个元素结尾的最大连续和
转移： d p [ i ] = max ( n u m s [ i ] , d p [ i − 1 ] + n u m s [ i ]) 边界： d p [ 0 ] = n u m s [ 0 ] 答案：dp数组内全部数值的最大值  # include <vector> # include <algorithm> using namespace std ; int maxSubArray ( vector < int > & nums ) { int n = nums . size ( ) ; vector < int > dp ( n ) ; dp [ 0 ] = nums [ 0 ] ; int maxSum = dp [ 0 ] ; for ( int i = 1 ; i < n ; i ++ ) { dp [ i ] = max ( nums [ i ] , dp [ i - 1 ] + nums [ i ] ) ; maxSum = max ( maxSum , dp [ i ] ) ; } return maxSum ; }  空间优化版本  int maxSubArrayOptimized ( vector < int > & nums ) { int n = nums . size ( ) ; int currentMax = nums [ 0 ] ; int maxSum = nums [ 0 ] ; for ( int i = 1 ; i < n ; i ++ ) { currentMax = max ( nums [ i ] , currentMax + nums [ i ] ) ; maxSum = max ( maxSum , currentMax ) ; } return maxSum ; }

55.3.1 01背包  题意：共 n 件物品，每件仅取一次；物品重量 w [ i ] 、价值 v [ i ] ，背包最大容量 C ，求可装入最大总价值。
状态： d p [ i ] [ j ] 前 i 件物品，容量 j 时最大价值
转移： d p [ i ] [ j ] = max ( d p [ i − 1 ] [ j ] , j ≥ w [ i ]? d p [ i − 1 ] [ j − w [ i ]] + v [ i ] : 0 ) 边界： d p [ 0 ] [ j ] = 0 , d p [ i ] [ 0 ] = 0 最终结果： d p [ n ] [ C ]  # include <vector> # include <algorithm> using namespace std ; int knapsack01 ( vector < int > & w , vector < int > & v , int C ) { int n = w . size ( ) ; vector < vector < int >> dp ( n + 1 , vector < int > ( C + 1 , 0 ) ) ; for ( int i = 1 ; i <= n ; i ++ ) { for ( int j = 1 ; j <= C ; j ++ ) { dp [ i ] [ j ] = dp [ i - 1 ] [ j ] ; if ( j >= w [ i - 1 ] ) { dp [ i ] [ j ] = max ( dp [ i ] [ j ] , dp [ i - 1 ] [ j - w [ i - 1 ] ] + v [ i - 1 ] ) ; } } } return dp [ n ] [ C ] ; }  一维空间优化（逆序遍历，防止重复选取）  int knapsack01Optimized ( vector < int > & w , vector < int > & v , int C ) { int n = w . size ( ) ; vector < int > dp ( C + 1 , 0 ) ; for ( int i = 0 ; i < n ; i ++ ) { for ( int j = C ; j >= w [ i ] ; j -- ) { dp [ j ] = max ( dp [ j ] , dp [ j - w [ i ] ] + v [ i ] ) ; } } return dp [ C ] ; }

52.1.3 存储方式  完全二叉树的节点编号具有规律性，因此最适合用数组存储，无需额外存储指针，节省空间：
数组下标从 1 开始（与节点编号对应），下标 i 存储编号为 i 的节点数据。
根节点存储在下标 1 ，左子节点在 2 i ，右子节点在 2 i + 1 ，父节点在 i /2 。  # define MAX_SIZE 100 //完全二叉树的数组存储 typedef struct { int data [ MAX_SIZE ] ; //存储节点数据(下标1开始) int n ; //节点总数 } CompleteBinaryTree ;

58.1.1 矩阵最小路径和  问题定义：给定一个包含非负整数的 m×n 矩阵，从左上角出发，每次只能向右或向下移动，到达右下角的最小路径和。
解题思路  状态定义： dp[i][j] 表示从左上角 (0,0) 到单元格 (i,j) 的最小路径和。 边界条件：
第一行 i=0,j>0 ：只能从左侧移动到达， dp[0][j] = dp[0][j-1] + grid[0][j] 第一列 j=0,i>0 ：只能从上方移动到达， dp[i][0] = dp[i-1][0] + grid[i][0] 普通情况 i>0,j>0 ：可从上方或左侧到达，取两者最小值  d p [ i ] [ j ] = min ( d p [ i − 1 ] [ j ] , d p [ i ] [ j − 1 ]) + g r i d [ i ] [ j ]  结果提取： dp[m-1][n-1]  完整代码  # include <vector> # include <algorithm> using namespace std ; int minPathSum ( vector < vector < int >> & grid ) { int m = grid . size ( ) ; int n = grid [ 0 ] . size ( ) ; vector < vector < int >> dp ( m , vector < int > ( n ) ) ; dp [ 0 ] [ 0 ] = grid [ 0 ] [ 0 ] ; // 填充第一行 for ( int j = 1 ; j < n ; j ++ ) { dp [ 0 ] [ j ] = dp [ 0 ] [ j - 1 ] + grid [ 0 ] [ j ] ; } // 填充第一列 for ( int i = 1 ; i < m ; i ++ ) { dp [ i ] [ 0 ] = dp [ i - 1 ] [ 0 ] + grid [ i ] [ 0 ] ; } // 填充其余单元格 for ( int i = 1 ; i < m ; i ++ ) { for ( int j = 1 ; j < n ; j ++ ) { dp [ i ] [ j ] = min ( dp [ i - 1 ] [ j ] , dp [ i ] [ j - 1 ] ) + grid [ i ] [ j ] ; } } return dp [ m - 1 ] [ n - 1 ] ; }  空间优化：仅保留一维数组，空间复杂度从 O ( mn ) 降至 O ( n )  int minPathSumOptimized ( vector < vector < int >> & grid ) { int m = grid . size ( ) ; int n = grid [ 0 ] . size ( ) ; vector < int > dp ( n ) ; dp [ 0 ] = grid [ 0 ] [ 0 ] ; // 初始化第一行 for ( int j = 1 ; j < n ; j ++ ) { dp [ j ] = dp [ j - 1 ] + grid [ 0 ] [ j ] ; } // 逐行计算 for ( int i = 1 ; i < m ; i ++ ) { dp [ 0 ] += grid [ i ] [ 0 ] ; for ( int j = 1 ; j < n ; j ++ ) { dp [ j ] = min ( dp [ j ] , dp [ j - 1 ] ) + grid [ i ] [ j ] ; } } return dp [ n - 1 ] ; }

58.1.2 最长公共子序列(LCS)  问题定义：给定两个字符串 s1 和 s2 ，求最长公共子序列长度（子序列不要求连续，仅保持字符顺序）。
解题思路  状态定义： dp[i][j] 表示 s1 前 i 个字符、 s2 前 j 个字符的最长公共子序列长度。 边界条件： dp[0][j]=0 、 dp[i][0]=0 ，空串无公共字符。 状态转移：
若 s1[i-1] == s2[j-1] ： d p [ i ] [ j ] = d p [ i − 1 ] [ j − 1 ] + 1 若字符不相等： d p [ i ] [ j ] = max ( d p [ i − 1 ] [ j ] , d p [ i ] [ j − 1 ])  完整二维代码  # include <vector> # include <string> using namespace std ; int longestCommonSubsequence ( string s1 , string s2 ) { int m = s1 . size ( ) ; int n = s2 . size ( ) ; vector < vector < int >> dp ( m + 1 , vector < int > ( n + 1 , 0 ) ) ; for ( int i = 1 ; i <= m ; i ++ ) { for ( int j = 1 ; j <= n ; j ++ ) { if ( s1 [ i - 1 ] == s2 [ j - 1 ] ) { dp [ i ] [ j ] = dp [ i - 1 ] [ j - 1 ] + 1 ; } else { dp [ i ] [ j ] = max ( dp [ i - 1 ] [ j ] , dp [ i ] [ j - 1 ] ) ; } } } return dp [ m ] [ n ] ; }  滚动数组空间优化  int longestCommonSubsequenceOptimized ( string s1 , string s2 ) { int m = s1 . size ( ) ; int n = s2 . size ( ) ; vector < int > dp ( n + 1 , 0 ) ; for ( int i = 1 ; i <= m ; i ++ ) { int prev = 0 ; for ( int j = 1 ; j <= n ; j ++ ) { int temp = dp [ j ] ; if ( s1 [ i - 1 ] == s2 [ j - 1 ] ) { dp [ j ] = prev + 1 ; } else { dp [ j ] = max ( dp [ j ] , dp [ j - 1 ] ) ; } prev = temp ; } } return dp [ n ] ; }
